            if ( !TableNumberingIndex( numbering, (const void *) pointee_value, index_value ) ) { return false; }
            w.putleb( ids.ref( 0x7ce4fd9430e80ceaull ) ); w.put8( 17 ); // value — a NODE INDEX into the flat node table
            w.putleb( index_value );
