// FleetLoadoutsEntryWireExtent: the extent FleetLoadoutsEntry's lists and maps command, from the FRAMING alone.
// It reads no field value, so a caller can refuse a number it did not
// expect before one byte is allocated (docs/SPEC-TABLES.md §6.5).
inline bool FleetLoadoutsEntryWireExtent( const uint8_t * body, int64_t length, int64_t & at, const TableIdTable * ids, TableRefuseReason & reason )
{
    TableReport scratch; // the scan's framing damage is the LOAD's to report
    TableReader r( body, length, &scratch, ids );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) ) { return true; }
        if ( field_ref == 0 ) { return true; }
        if ( ids == NULL || field_ref > (uint64_t) ids->count ) { return true; }
        const uint64_t field_id = ids->at( field_ref );
        if ( !r.has( 1 ) ) { return true; }
        uint8_t field_kind = r.get8();
        if ( field_id == 0x7ce4fd9430e80ceaull && field_kind == 14 ) // value
        {
            uint64_t map_len = 0;
            if ( !r.getleb( map_len ) || !r.room( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += (int64_t) map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetLoadoutsEntryValueEntry ), (int64_t) alignof( FleetLoadoutsEntryValueEntry ), NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( !r.skip( field_kind ) ) { return true; }
    }
}

// FleetLoadoutsEntryExtentAt: the node extent FleetLoadoutsEntry's lists and maps take, PRE-ORDER, advancing
// the running offset exactly as FleetLoadoutsEntryExtentPack advances it (§2.8, §2.9).
template <typename Ctx>
inline bool FleetLoadoutsEntryExtentAt( const Ctx & ctx, const FleetLoadoutsEntry & value, int64_t & at )
{
    {
        TableMapCursor<FleetLoadoutsEntryValueEntry> cursor = TableMapOrder( ctx, value.value );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( FleetLoadoutsEntryValueEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntryValueEntry ); // the whole array FIRST
        TableMapRelease( cursor );
    }
    return true;
}

// the whole extent of one node, from a fresh offset: what a pack reserves
// for it beside the record's own storage.
template <typename Ctx>
inline int64_t FleetLoadoutsEntryExtent( const Ctx & ctx, const FleetLoadoutsEntry & value )
{
    int64_t at = 0;
    if ( !FleetLoadoutsEntryExtentAt( ctx, value, at ) ) { return -1; }
    return at;
}

// FleetLoadoutsEntryExtentPack: carve FleetLoadoutsEntry's arrays out of the node's extent and copy the
// entries in ASCENDING key order and the elements in INDEX order, PRE-ORDER,
// advancing the same running offset FleetLoadoutsEntryExtentAt advances (§2.8, §2.9).
template <typename Ctx>
inline bool FleetLoadoutsEntryExtentPack( const Ctx & ctx, const FleetLoadoutsEntry & src, FleetLoadoutsEntry & dst, uint8_t * extent, int64_t & at, int64_t capacity )
{
    {
        TableMapCursor<FleetLoadoutsEntryValueEntry> cursor = TableMapOrder( ctx, src.value );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntryValueEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetLoadoutsEntryValueEntry * placed = (FleetLoadoutsEntryValueEntry *) ( extent + at );
        at += bytes;
        dst.value.count = cursor.count;
        dst.value.padding = 0;
        dst.value.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.value.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetLoadoutsEntryValueEntry ) ); // trivially copyable, by construction
        }
        TableMapRelease( cursor );
    }
    return true;
}

// FleetWireExtent: the extent Fleet's lists and maps command, from the FRAMING alone.
// It reads no field value, so a caller can refuse a number it did not
// expect before one byte is allocated (docs/SPEC-TABLES.md §6.5).
inline bool FleetWireExtent( const uint8_t * body, int64_t length, int64_t & at, const TableIdTable * ids, TableRefuseReason & reason )
{
    TableReport scratch; // the scan's framing damage is the LOAD's to report
    TableReader r( body, length, &scratch, ids );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) ) { return true; }
        if ( field_ref == 0 ) { return true; }
        if ( ids == NULL || field_ref > (uint64_t) ids->count ) { return true; }
        const uint64_t field_id = ids->at( field_ref );
        if ( !r.has( 1 ) ) { return true; }
        uint8_t field_kind = r.get8();
        if ( field_id == 0x294a5c4913e1ad44ull && field_kind == 14 ) // ships
        {
            uint64_t map_len = 0;
            if ( !r.getleb( map_len ) || !r.room( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += (int64_t) map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetShipsEntry ), (int64_t) alignof( FleetShipsEntry ), NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( field_id == 0x7b024c46e98d3404ull && field_kind == 14 ) // by_id
        {
            uint64_t map_len = 0;
            if ( !r.getleb( map_len ) || !r.room( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += (int64_t) map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetByIdEntry ), (int64_t) alignof( FleetByIdEntry ), NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( field_id == 0x294fa1b3f0f5f070ull && field_kind == 14 ) // loadouts
        {
            uint64_t map_len = 0;
            if ( !r.getleb( map_len ) || !r.room( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += (int64_t) map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetLoadoutsEntry ), (int64_t) alignof( FleetLoadoutsEntry ), &FleetLoadoutsEntryWireExtent, ids, reason ) ) { return false; }
            continue;
        }
        if ( field_id == 0x6dd8dc6c5fdae3ceull && field_kind == 14 ) // tiers
        {
            uint64_t map_len = 0;
            if ( !r.getleb( map_len ) || !r.room( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += (int64_t) map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetTiersEntry ), (int64_t) alignof( FleetTiersEntry ), NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( !r.skip( field_kind ) ) { return true; }
    }
}

// FleetExtentAt: the node extent Fleet's lists and maps take, PRE-ORDER, advancing
// the running offset exactly as FleetExtentPack advances it (§2.8, §2.9).
template <typename Ctx>
inline bool FleetExtentAt( const Ctx & ctx, const Fleet & value, int64_t & at )
{
    {
        TableMapCursor<FleetShipsEntry> cursor = TableMapOrder( ctx, value.ships );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( FleetShipsEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetShipsEntry ); // the whole array FIRST
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetByIdEntry> cursor = TableMapOrder( ctx, value.by_id );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( FleetByIdEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetByIdEntry ); // the whole array FIRST
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, entry by entry in key order
        {
            if ( !FleetByIdEntryExtentAt( ctx, *cursor[i], at ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetLoadoutsEntry> cursor = TableMapOrder( ctx, value.loadouts );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( FleetLoadoutsEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntry ); // the whole array FIRST
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, entry by entry in key order
        {
            if ( !FleetLoadoutsEntryExtentAt( ctx, *cursor[i], at ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetTiersEntry> cursor = TableMapOrder( ctx, value.tiers );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( FleetTiersEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetTiersEntry ); // the whole array FIRST
        TableMapRelease( cursor );
    }
    return true;
}

// the whole extent of one node, from a fresh offset: what a pack reserves
// for it beside the record's own storage.
template <typename Ctx>
inline int64_t FleetExtent( const Ctx & ctx, const Fleet & value )
{
    int64_t at = 0;
    if ( !FleetExtentAt( ctx, value, at ) ) { return -1; }
    return at;
}

// FleetExtentPack: carve Fleet's arrays out of the node's extent and copy the
// entries in ASCENDING key order and the elements in INDEX order, PRE-ORDER,
// advancing the same running offset FleetExtentAt advances (§2.8, §2.9).
template <typename Ctx>
inline bool FleetExtentPack( const Ctx & ctx, const Fleet & src, Fleet & dst, uint8_t * extent, int64_t & at, int64_t capacity )
{
    {
        TableMapCursor<FleetShipsEntry> cursor = TableMapOrder( ctx, src.ships );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetShipsEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetShipsEntry * placed = (FleetShipsEntry *) ( extent + at );
        at += bytes;
        dst.ships.count = cursor.count;
        dst.ships.padding = 0;
        dst.ships.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.ships.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetShipsEntry ) ); // trivially copyable, by construction
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetByIdEntry> cursor = TableMapOrder( ctx, src.by_id );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetByIdEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetByIdEntry * placed = (FleetByIdEntry *) ( extent + at );
        at += bytes;
        dst.by_id.count = cursor.count;
        dst.by_id.padding = 0;
        dst.by_id.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.by_id.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetByIdEntry ) ); // trivially copyable, by construction
        }
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            if ( !FleetByIdEntryExtentPack( ctx, *cursor[i], placed[i], extent, at, capacity ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetLoadoutsEntry> cursor = TableMapOrder( ctx, src.loadouts );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetLoadoutsEntry * placed = (FleetLoadoutsEntry *) ( extent + at );
        at += bytes;
        dst.loadouts.count = cursor.count;
        dst.loadouts.padding = 0;
        dst.loadouts.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.loadouts.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetLoadoutsEntry ) ); // trivially copyable, by construction
        }
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            if ( !FleetLoadoutsEntryExtentPack( ctx, *cursor[i], placed[i], extent, at, capacity ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetTiersEntry> cursor = TableMapOrder( ctx, src.tiers );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetTiersEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetTiersEntry * placed = (FleetTiersEntry *) ( extent + at );
        at += bytes;
        dst.tiers.count = cursor.count;
        dst.tiers.padding = 0;
        dst.tiers.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.tiers.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetTiersEntry ) ); // trivially copyable, by construction
        }
        TableMapRelease( cursor );
    }
    return true;
}

// ---- FleetLoadoutsEntry.value: the builder's five and the side index (§2.8) ----

// INSERT: the key is copied, the value is handed back at its defaults to
// fill. A DUPLICATE key REPLACES — the value is reset and the same entry
// handed back, key and address unchanged — so a caller that wants to know
// writes Find first. NULL is NOT INSERTED: a key longer than the bound,
// because a truncated key would be a merged entry, and an arena that
// cannot carve another segment, alike.
//
// It is a WRAPPER: TableMapPlace owns the lookup, the reset, the
// allocation and the key copy, and this half is the bound and the
// const char * key's length. Nothing here mutates an entry (§2.8).
inline Item * FleetLoadoutsEntryValueInsert( TableWorker & worker, TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    FleetLoadoutsEntryValueEntry * entry = TableMapPlace( worker, map, key );
    return entry != NULL ? TableEntryValue( entry ) : NULL;
}

// FIND on the builder: the same linear scan, O( n ) key compares over the
// segments in insertion order. NULL when absent. The builder builds NO
// INDEX, and that is a rule — the sort happens once, at Lock, Save or
// Cook, and every lookup that matters runs over the sorted region.
inline Item * FleetLoadoutsEntryValueFind( TableArena & arena, TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    FleetLoadoutsEntryValueEntry * found = TableMapScan( arena, map, key );
    return found != NULL ? TableEntryValue( found ) : NULL;
}

// ERASE: marks the entry DEAD, one bit in the segment's slot and not in the
// entry table. False when absent. Its storage is held until the builder
// resets and never reused mid-build, because reusing a slot would make "an
// entry's address is stable" false for exactly one case.
inline bool FleetLoadoutsEntryValueErase( TableArena & arena, TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    return TableMapErase( arena, map, key );
}

// EACH on the builder: INSERTION order, live entries only.
inline TableMapEach<FleetLoadoutsEntryValueEntry> FleetLoadoutsEntryValueEach( const TableArena & arena, const TableMap<FleetLoadoutsEntryValueEntry> & map )
{
    return TableMapEachOf( arena, map );
}

// ---- the OPTIONAL INDEX: caller-owned, built at load, never stored ----
//
// Open addressing with linear probing over the sorted array, for a map large
// enough that log n compares over a cold array cost more than one hash and a
// probe. ITS HASH AND ITS LOAD FACTOR ARE NOT A CROSS-PORT CONTRACT: the
// index is never stored, so no golden, no cook-check rule and no
// build-version line ever names either. What a port is held to is the
// CONTRACT of the lookup — the same value the sorted array's Find returns
// for the same key, and no allocation past the storage the caller handed in.
inline int64_t FleetLoadoutsEntryValueIndexMeasure( const TableMap<FleetLoadoutsEntryValueEntry> & map )
{
    return (int64_t) TableMapIndexSlots( map.count ) * (int64_t) sizeof( int32_t );
}

inline TableMapIndex FleetLoadoutsEntryValueIndex( const TableMap<FleetLoadoutsEntryValueEntry> & map, void * storage, int64_t bytes )
{
    TableMapIndex index;
    const int32_t slots = TableMapIndexSlots( map.count );
    if ( storage == NULL || bytes < (int64_t) slots * (int64_t) sizeof( int32_t ) ) { return index; }
    index.slots = (int32_t *) storage;
    index.capacity = slots;
    for ( int32_t i = 0; i < slots; i++ ) { index.slots[i] = 0; }
    const FleetLoadoutsEntryValueEntry * entries = map.Entries();
    for ( int32_t i = 0; i < map.count; i++ ) // ONE PASS over the sorted array
    {
        int32_t at = (int32_t) ( TableMapHash( (uint64_t) entries[i].key ) & (uint64_t) ( slots - 1 ) );
        while ( index.slots[at] != 0 ) { at = ( at + 1 ) & ( slots - 1 ); }
        index.slots[at] = i + 1; // slots are ENTRY INDICES; 0 is an empty slot
    }
    index.good = true;
    return index;
}

inline const Item * FleetLoadoutsEntryValueIndexFind( const TableMapIndex & index, const TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    if ( !index.good ) { return map.Find( key ); } // an index that did not build is not a wrong answer
    const FleetLoadoutsEntryValueEntry * entries = map.Entries();
    int32_t at = (int32_t) ( TableMapHash( (uint64_t) key ) & (uint64_t) ( index.capacity - 1 ) );
    for ( int32_t probe = 0; probe < index.capacity; probe++ )
    {
        const int32_t slot = index.slots[at];
        if ( slot == 0 ) { return NULL; }
        if ( TableEntryOrder( entries[slot - 1], key ) == 0 ) { return TableEntryFound( entries + slot - 1 ); }
        at = ( at + 1 ) & ( index.capacity - 1 );
    }
    return NULL;
}

