// ShipConfigCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// ShipConfig IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t ShipConfigCookMeasure( const ShipConfig & value )
{
    (void) value;
    return 160; // 64 header + 80 data + 16 attribution
}

// ShipConfigCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract ShipConfigMeasure/ShipConfigSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool ShipConfigCook( const ShipConfig & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) ShipConfigCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 80, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    ShipConfigCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 144, 0, 8, order );
    table_cook_put( raw + 152, 0x758252d2d1b14f0dull, 8, order );
    return true;
}

// ItemCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// Item IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t ItemCookMeasure( const Item & value )
{
    (void) value;
    return 88; // 64 header + 8 data + 16 attribution
}

// ItemCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract ItemMeasure/ItemSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool ItemCook( const Item & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) ItemCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 8, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    ItemCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 72, 0, 8, order );
    table_cook_put( raw + 80, 0x52cfa1d198476806ull, 8, order );
    return true;
}

// FleetCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
// A NODE'S SIZE DEPENDS ON ITS VALUE where a list or a map rides in its extent
// (docs/SPEC-TABLES.md §2.8), so the layout takes the resolution context
// the numbering walked and reads the same arrays that walk read.
template <typename Ctx>
inline bool FleetCookLayout( const Ctx & ctx, const Fleet & root, const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    const int64_t root_extent = FleetExtent( ctx, root );
    if ( root_extent < 0 ) { return false; }
    int64_t offset = 72 + root_extent; // the root at zero, its extent behind it
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            case 0x758252d2d1b14f0dull: size = 76; node_align = 4; break; // ShipConfig
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// FleetCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t FleetCookMeasureFrom( const Ctx & ctx, const Fleet & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( FleetNumberFrom( ctx, numbering, root ) && FleetCookLayout( ctx, root, numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// FleetCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool FleetCookFrom( const Ctx & ctx, const Fleet & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = FleetNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && FleetCookLayout( ctx, root, numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = FleetCookNode( ctx, region, region.base, root, order );
            for ( int64_t k = 0; ok && k < numbering.count; k++ )
            {
                uint8_t * at = region.base + region.offsets[k + 1];
                const void * node = numbering.entries[k].node;
                switch ( numbering.entries[k].type_id )
                {
                    case 0x758252d2d1b14f0dull: ok = ShipConfigCookNode( ctx, region, at, *(const ShipConfig *) node, order ); break; // ShipConfig
                    default: ok = false; break;
                }
            }
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0x0a53e00afba279afull, 8, order ); // the root: fnv1a64( "Fleet" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// FleetCookMeasure / FleetCook over a REGION root — a locked builder's AsConst, a
// region FleetLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t FleetCookMeasure( const Fleet * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FleetCookMeasureFrom( ctx, *root, allocator );
}

inline bool FleetCook( const Fleet * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return FleetCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t FleetCookMeasure( const FleetBuilder & builder )
{
    if ( builder.region != NULL ) { return FleetCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FleetCookMeasureFrom( ctx, *(const Fleet *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool FleetCook( const FleetBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return FleetCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FleetCookFrom( ctx, *(const Fleet *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
// A pointer FIELD is a TableRef — eight bytes and no address — so the
// property holds in BOTH forms: a fixed-size table is one relocatable
// struct, and a packed region is one relocatable block whose references
// are self-relative and therefore survive a plain memcpy.
static_assert( __is_trivially_copyable( ShipConfig ), "ShipConfig must stay relocatable" );
static_assert( __is_standard_layout( ShipConfig ), "ShipConfig must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Item ), "Item must stay relocatable" );
static_assert( __is_standard_layout( Item ), "Item must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( FleetShipsEntry ), "FleetShipsEntry must stay relocatable" );
static_assert( __is_standard_layout( FleetShipsEntry ), "FleetShipsEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( FleetByIdEntry ), "FleetByIdEntry must stay relocatable" );
static_assert( __is_standard_layout( FleetByIdEntry ), "FleetByIdEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( FleetLoadoutsEntryValueEntry ), "FleetLoadoutsEntryValueEntry must stay relocatable" );
static_assert( __is_standard_layout( FleetLoadoutsEntryValueEntry ), "FleetLoadoutsEntryValueEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( FleetLoadoutsEntry ), "FleetLoadoutsEntry must stay relocatable" );
static_assert( __is_standard_layout( FleetLoadoutsEntry ), "FleetLoadoutsEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( FleetTiersEntry ), "FleetTiersEntry must stay relocatable" );
static_assert( __is_standard_layout( FleetTiersEntry ), "FleetTiersEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Fleet ), "Fleet must stay relocatable" );
static_assert( __is_standard_layout( Fleet ), "Fleet must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( ShipConfig ) == 76, "ShipConfig's sizeof moved: the build version was taken over 76, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( ShipConfig ) == 4, "ShipConfig's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
